!==================================================!
!   Map Region 6 PV/reference codes to habitats   !
!==================================================!
! VBASE $Id$
subroutine PVREF6 (KARD2,ARRAY2,LPVCOD,LPVREF)
  implicit none

  !     MAPS PV/REFERENCE CODES INTO A FVS HABITAT/ECOCLASS CODE
  !     CALLED FROM **HABTYP** WHEN REFTMP IS GREATER THAN ZERO

  !     INPUT VARIABLES
  !     KARD2          - FIELD 2 OF STDINFO KEYWORD
  !     ARRAY2         - FIELD 2 OF STDINFO (REAL CONTERPART TO KARD2)
  !     CPVREF         - FIELD 7 OF STDINFO KEYWORD
  !                    - IN PLOT.F77

  !     RETURN VARIABLES
  !     KARD2          - MAPPED FVS HABITAT/ECOCLASS CODE

  !     INTERNAL VARIABLES
  !     PVCODE,PVREF   - ARRAYS OF PV CODE/REFERENCE CODE COMBINATIONS
  !                      FROM FSVEG DATA BASE
  !     HABPVR         - FVS HABITAT/ECOCLASS CODE CORRESPONDING TO
  !                      PV CODE/REFERENCE CODE COMBINATION, ONE COLUMN
  !                      PER VARIANT (COLUMN IV, CHOSEN FROM VARIANTCD)

  !  SHARED BY BM, CA, EC, NC, OC, OP, PN, SO AND WC. EACH VARIANT USED TO
  !  CARRY ITS OWN TABLE OF 2,763 TO 4,175 ROWS, MOSTLY THE SAME PV/REFERENCE
  !  PAIRS. THE TABLE BELOW HOLDS EVERY PAIR ONCE, ORDERED BY REFERENCE CODE
  !  AND PV CODE, WITH EACH VARIANT'S HABITAT CODE IN ITS OWN COLUMN. '-'
  !  MARKS A PAIR THAT VARIANT'S TABLE DID NOT CONTAIN; SUCH ROWS ARE SKIPPED,
  !  SO THEY NEITHER MATCH NOR SET LPVCOD/LPVREF. A BLANK HABITAT CODE IS A
  !  REAL ENTRY AND IS RETURNED AS IT WAS. EACH VARIANT'S PAIRS WERE UNIQUE,
  !  EXCEPT THAT BM LISTED THE BLANK PAIR FOUR TIMES (CAG4, CEF411, CLS5,
  !  CLS6); ONLY THE FIRST, CAG4, COULD EVER BE RETURNED, SO IT IS KEPT.

  ! Common blocks
  include 'PRGPRM.f90'
  include 'PLOT.f90'

  ! Variables
  integer :: NCODES
  parameter (NCODES = 4277)

