  character(len=10) :: KARD2
  character(len=10) :: KARD2T

  character(len=10) :: HABPVR(7,NCODES)
  character(len=10) :: PVCODE(NCODES)
  character(len=10) :: PVREF(NCODES)
  save HABPVR,PVCODE,PVREF

  integer :: I,IV,J

  real    :: ARRAY2

